SET SCHEMA "BSCL";


/*Tablas*/
SET SCHEMA "BSCL";
DROP TYPE "BSCL.Normativo.BD::NOR.SALIDA_INFORMEDERECHO" CASCADE;
CREATE TYPE "BSCL.Normativo.BD::NOR.SALIDA_INFORMEDERECHO" AS TABLE ( 
"TipoRegistro" 			NVARCHAR(1)  DEFAULT '' NULL
,"Folio" 				NVARCHAR(6)  DEFAULT '' NULL
,"Mercado"				NVARCHAR(2)  DEFAULT '' NULL
,"CorredorCompra" 		NVARCHAR(3)  DEFAULT '' NULL
,"CorredorVenta" 		NVARCHAR(3)  DEFAULT '' NULL
,"FechaVencimiento"		NVARCHAR(10)  DEFAULT '' NULL
,"Nemotecnico" 			NVARCHAR(10)  DEFAULT '' NULL
,"Precio" 				NVARCHAR(17)  DEFAULT '' NULL
,"Tasa"					NVARCHAR(7)  DEFAULT '' NULL
,"SignoTasa"			NVARCHAR(1)  DEFAULT '' NULL
,"DocumentoIdentidad"	NVARCHAR(11)  DEFAULT '' NULL
,"Cantidad" 			NVARCHAR(17)  DEFAULT '' NULL
,"TipoOperacion"		NVARCHAR(1)  DEFAULT '' NULL
,"TipoReajuste" 		NVARCHAR(2)  DEFAULT '' NULL
,"Monto"				NVARCHAR(17)  DEFAULT '' NULL
,"Emisor" 				NVARCHAR(10)  DEFAULT '' NULL
,"RegistroConcatenado" 	NVARCHAR(121)  DEFAULT '' NULL
);

delete FROM "BSCL"."BSCL.Normativa.BD::DOC.Esquema" N WHERE N."Esquema"='INFDERECH' AND "Version"='2016';

select
    'INFDERECH' as "Esquema",
    '2023' as "Version",
    'NOR' as "Modulo",
    'D' as "Periodicidad",
    'mostrar los cliente con derecho' as "Objetivo",
    '' as "PeriodoInicio",
    '' as "IdEntidadReguladora",
    '2023-12-31' as "FechaPresentacionLimite",
    '2023-01-01' as "FechaDatosDesde",
    '2023-12-31' as "FechaDatosHasta",
	 0 as "CodigoVersionSII",
	'N' as "HabilitadoMantenedor"
from dummy WHERE NOT EXISTS (SELECT 1 FROM "BSCL"."BSCL.Normativa.BD::DOC.Esquema" N WHERE N."Esquema"='INFDERECH' AND "Version"='2023');

DELETE FROM "BSCL.Normativa.BD::DOC.Campo" WHERE "Esquema"='INFDERECH';

select 'INFDERECH' as "Esquema", '2023' as "Version", 'RegistroConcatenado' as "Nombre"   , '' as "CodigoSII", '' as "TipoDiccionario", 1 as "Orden", 'RegConcatenado' as "Titulo"		, 'Ayuda de	Reg_Concatenado' as "Ayuda"	, 'TEXT' as "TipoDato", 0 as "Largo", '0' as "ValorDefecto", ' ' as "Obligatorio",  'S' as "Editable",  'N' as "ModoMasivo", 'S' as "Exportable", 'S' as "OcultoEnGrilla", 'S' as "OcultoEnMantenedor", 'S' as "Comun", 'N' as "Clave", '' as "Grupo", 0 as "OrdenCargaExterna",0 as "CantidadDecimales" from dummy;


select 'INFDERECH','Informe Derechos','INFDERECH','N','INFDERECH','INFDERECH','INFDERECH'
FROM dummy WHERE NOT EXISTS (SELECT 1 FROM "BSCL"."BSCL.Normativa.BD::DOC.TipoDocumento" N WHERE N."IdTipoDocumento"='INFDERECH');




/* Copia de Informe de Derechos TP a Tandem */

			
 DELETE FROM BSCL."BSCL.Normativa.BD::DOC.Parametro" N WHERE N."Esquema"='INFDERECH' AND N."Codigo"='NOMBRE_ENVIO_TANDEM_SVS';
 DELETE FROM BSCL."BSCL.Normativa.BD::DOC.Parametro" N WHERE N."Esquema"='INFDERECH' AND N."Codigo"='NOMBRE_ENVIO_TANDEM_CUS';
 
SELECT 'INFDERECH', '2023', 'NOMBRE_ENVIO_TANDEM_CUS', 'Nombre archivo enviado a ruta Tadem CUS ', 'TP[CODCORREDOR][MESTRAN][DIATRAN]','N','','TP[CODCORREDOR][MESTRAN][DIATRAN]', 'texto libre o vacio [CODCORREDOR] [MESTRAN] [DIATRAN]', '','', 'CFLORES ',  CURRENT_UTCTIMESTAMP, ' ', CURRENT_UTCTIMESTAMP, ' ', 1
FROM dummy WHERE 
 NOT EXISTS (SELECT 1 FROM BSCL."BSCL.Normativa.BD::DOC.Parametro" N WHERE N."Esquema"='INFDERECH' AND N."Codigo"='NOMBRE_ENVIO_TANDEM_CUS');
			
SELECT 'NOMBRE_ENVIO_TANDEM_SVS', 'SOLICITUD', 'Nombre de envio a Tandem', 'N', 'N'
FROM dummy WHERE 
 NOT EXISTS (SELECT 1 FROM BSCL."BSCL.Normativa.BD::NOR.TipoParametros" N WHERE N."TipoParametro"='NOMBRE_ENVIO_TANDEM_SVS');
 
 
SELECT 'NOMBRE_ENVIO_TANDEM_CUS', 'SOLICITUD', 'Nombre de envio a Tandem cus', 'N', 'N'
FROM dummy WHERE 
 NOT EXISTS (SELECT 1 FROM BSCL."BSCL.Normativa.BD::NOR.TipoParametros" N WHERE N."TipoParametro"='NOMBRE_ENVIO_TANDEM_CUS');
	
